import { createHash } from "node:crypto";

// TOTVS WinThor: a API roda no WinThor Anywhere (WTA) do cliente. Não há host público.
const BASE = process.env.WINTHOR_BASE_URL!;   // http://<<IP_OU_HOST_DO_WTA>>:<<PORTA_DO_WTA>>
const USUARIO = process.env.WINTHOR_USUARIO!; // <<USUARIO_DE_INTEGRACAO>>
const SENHA = process.env.WINTHOR_SENHA!;     // <<SENHA_DO_WTA>> em texto

// Regra da TDN: senha em maiúsculas -> MD5 -> hash em maiúsculas
const senhaWta = (s: string) => createHash("md5").update(s.toUpperCase(), "utf8").digest("hex").toUpperCase();

async function abrirSessao(): Promise<Record<string, string>> {
  const r = await fetch(`${BASE}/winthor/autenticacao/v1/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json" },
    body: JSON.stringify({ login: USUARIO, senha: senhaWta(SENHA) }),
  });
  if (!r.ok) throw new Error(`Login recusado: HTTP ${r.status} ${await r.text()}`);
  const { accessToken } = (await r.json()) as { accessToken: string }; // JWT de 4 h
  // Transporte documentado: cookie. fetch não guarda cookie; reenviamos o Set-Cookie recebido
  // e também o Bearer (documentado só na API de liberação de pedido).
  const cookie = (r.headers.get("set-cookie") ?? "").split(";")[0];
  return {
    Accept: "application/json",
    "Content-Type": "application/json",
    Authorization: `Bearer ${accessToken}`,
    ...(cookie ? { Cookie: cookie } : {}),
  };
}

async function chamar(h: Record<string, string>, metodo: string, caminho: string,
                      params: Record<string, string> = {}, corpo?: unknown): Promise<any> {
  const url = `${BASE}${caminho}${Object.keys(params).length ? "?" + new URLSearchParams(params) : ""}`;
  for (let t = 0; t < 3; t++) {
    const r = await fetch(url, { method: metodo, headers: h, body: corpo ? JSON.stringify(corpo) : undefined });
    if ([502, 503, 504].includes(r.status)) { await new Promise((ok) => setTimeout(ok, 2000 * (t + 1))); continue; }
    if (r.status === 403) throw new Error("403: sessão não autenticada ou expirada; refaça o login");
    if (r.status === 404) throw new Error("404: serviço não instalado no WTA ou caminho errado");
    if (!r.ok) throw new Error(`WinThor respondeu HTTP ${r.status}: ${await r.text()}`);
    const texto = await r.text();
    return texto ? JSON.parse(texto) : null;
  }
  throw new Error("WTA indisponível: tentativas esgotadas");
}

async function listar(h: Record<string, string>, caminho: string, filtros: Record<string, string>,
                      pPagina = "page", pTamanho = "pageSize", tamanho = 100) {
  const registros: any[] = [];
  for (let pagina = 1; ; pagina++) {
    const corpo = await chamar(h, "GET", caminho, { ...filtros, [pPagina]: String(pagina), [pTamanho]: String(tamanho) });
    registros.push(...(corpo?.items ?? []));
    if (!corpo?.hasNext) return registros;
  }
}
